<script>
document.addEventListener('DOMContentLoaded',()=>{const list=document.querySelector('.collection-sort-list');if(!list)return;let drag=null;list.querySelectorAll('.collection-sort-item').forEach(item=>{item.addEventListener('dragstart',()=>{drag=item;item.classList.add('opacity-50')});item.addEventListener('dragend',()=>{item.classList.remove('opacity-50');drag=null});item.addEventListener('dragover',e=>{e.preventDefault();if(drag&&drag!==item){const box=item.getBoundingClientRect();const after=e.clientY>box.top+box.height/2;item.parentNode.insertBefore(drag,after?item.nextSibling:item)}})})});
</script>
